StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:				HE_FCx02_Drive_State
//	CREATOR:			Helgevold - William Veim
//
// REQUIREMENTS: Danfoss FC102 or FC202
// DESCRTIPTION: 	Generates a string with Status code and description
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0.0				2025-02-25		William Veim			Initial release
//	 1.0.1				2026-01-05		William Veim			Added reverse running as input
//
//================================================================================================================================


// Initilize
Wrk_StatusValue.Wrd := Inp_VFDStateCode;
Wrk_StateString := '';
Wrk_StateDescription := '';

CASE WORD_TO_UINT(Wrk_StatusValue.Wrd) OF 
	
	0:
	Wrk_StateCode:='0';
	Wrk_StateDescription:='Constant speed';

	1:
	Wrk_StateCode:='1';
	Wrk_StateDescription:='Constant frequency';
	
	3:
	Wrk_StateCode:='3';
	Wrk_StateDescription:='Constant head';
	
	4:
	Wrk_StateCode:='4';
	Wrk_StateDescription:='Constant pressure';
	
	5:
	Wrk_StateCode:='5';
	Wrk_StateDescription:='Constant diff. pressure';
	
	6:
	Wrk_StateCode:='6';
	Wrk_StateDescription:='Proportional pressure';
	
	7:
	Wrk_StateCode:='7';
	Wrk_StateDescription:='Constant flow';
	
	8:
	Wrk_StateCode:='8';
	Wrk_StateDescription:='Constant temperature';
	
	9:
	Wrk_StateCode:='9';
	Wrk_StateDescription:='Constant temperature diff.';
	
	10:
	Wrk_StateCode:='10';
	Wrk_StateDescription:='Constant level';
	
	128:
	Wrk_StateCode:='128';
	Wrk_StateDescription:='Auto adaption';
	
	129:
	Wrk_StateCode:='129';
	Wrk_StateDescription:='Flow adaption';
	
	130:
	Wrk_StateCode:='130';
	Wrk_StateDescription:='Closed loop sensor control';
	
END_CASE;

// Add Status Code
IF TestABit(In:=Cfg_Composition, Pos:=0) THEN
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_StateCode);
END_IF;	

// Add State Description
IF TestABit(In:=Cfg_Composition, Pos:=1) THEN
	IF LEN(Wrk_StateString) > 0 THEN
		Wrk_StateString := CONCAT(Wrk_StateString, Cfg_Delimiter);
	END_IF;
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_StateDescription);
END_IF;

HE_CIM500_Drive_State := Wrk_StateString;
